('combat_panel_private.multiplication_layout_options_for_figure(uuid,integer,text,uuid,uuid,bigint,integer)','{"acl": "{postgres=X/postgres}", "oid": "45714", "kind": "f", "nargs": 7, "owner": "postgres", "config": ["search_path=\"\""], "secdef": true, "strict": false, "ddl_md5": "e5ce060aa1143ae72fa2b8377566e034", "nspname": "combat_panel_private", "proname": "multiplication_layout_options_for_figure", "returns": "jsonb", "defaults": null, "language": "plpgsql", "parallel": "u", "arg_modes": null, "arg_names": ["p_actor", "p_copies", "p_mode", "p_target", "p_formation", "p_version", "p_index"], "arg_types": "2950 23 25 2950 2950 20 23", "arguments": "p_actor uuid, p_copies integer, p_mode text, p_target uuid, p_formation uuid, p_version bigint, p_index integer", "ddl_bytes": 11997, "leakproof": false, "signature": "combat_panel_private.multiplication_layout_options_for_figure(uuid,integer,text,uuid,uuid,bigint,integer)", "ddl_sha256": "1d35dd6bc7ca54083fd23a870d9a6818fb3d4d0a016a27783838639ff721a846", "return_oid": "3802", "source_md5": "3e4184f1bfe0bafe5cde44b08e552b1a", "volatility": "v", "returns_set": false, "source_bytes": 11697, "all_arg_types": null, "source_sha256": "5f4094c6dc391c0edb7bb46ac5f8fcf67e01780fca966ff76b1bd32e09143936", "variadic_type": "0", "default_arg_count": 0}'::jsonb),
('public.combat_v2_actor_ability(uuid,text,uuid,boolean)','{"acl": "{postgres=X/postgres,service_role=X/postgres}", "oid": "31311", "kind": "f", "nargs": 4, "owner": "postgres", "config": ["search_path=\"\""], "secdef": true, "strict": false, "ddl_md5": "916710a78b0cf41dd6af1a6e5eb2a33e", "nspname": "public", "proname": "combat_v2_actor_ability", "returns": "jsonb", "defaults": "false", "language": "sql", "parallel": "u", "arg_modes": null, "arg_names": ["p_actor", "p_source", "p_ability", "p_defense"], "arg_types": "2950 25 2950 16", "arguments": "p_actor uuid, p_source text, p_ability uuid, p_defense boolean DEFAULT false", "ddl_bytes": 2654, "leakproof": false, "signature": "public.combat_v2_actor_ability(uuid,text,uuid,boolean)", "ddl_sha256": "3d8ec0353d7c170c3260fecac22a83f28489291909e22bafba853adc35c3cb94", "return_oid": "3802", "source_md5": "b6180f3bc0d3ec90d2c18dac3c6f54e8", "volatility": "s", "returns_set": false, "source_bytes": 2417, "all_arg_types": null, "source_sha256": "760252065f0e0db9c3b3acc983a07779e173477131f850e04bd90a2e6184194f", "variadic_type": "0", "default_arg_count": 1}'::jsonb)),
fn AS MATERIALIZED(
 SELECT t.signature,t.expected,p.*,n.nspname,l.lanname,
 pg_get_functiondef(p.oid) actual_ddl,pg_get_userbyid(p.proowner) function_owner
 FROM targets t JOIN pg_proc p ON p.oid=to_regprocedure(t.signature)
 JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang),
headers AS MATERIALIZED(
 SELECT signature,expected,
 jsonb_build_object('signature',signature,'oid',oid::text,'nspname',nspname,'proname',proname,'kind',prokind::text,
 'owner',function_owner,'acl',proacl::text,'language',lanname,'config',to_jsonb(proconfig),'secdef',prosecdef,
 'volatility',provolatile::text,'parallel',proparallel::text,'strict',proisstrict,'leakproof',proleakproof,
 'arg_types',proargtypes::text,'all_arg_types',to_jsonb(proallargtypes),'arg_modes',to_jsonb(proargmodes),'arg_names',to_jsonb(proargnames),
 'nargs',pronargs,'default_arg_count',pronargdefaults,'defaults',pg_get_expr(proargdefaults,0),
 'variadic_type',provariadic::text,'return_oid',prorettype::text,'returns_set',proretset,
 'arguments',pg_get_function_arguments(oid),'returns',pg_get_function_result(oid),
 'ddl_md5',md5(actual_ddl),'source_md5',md5(prosrc),'ddl_sha256',encode(extensions.digest(convert_to(actual_ddl,'UTF8'),'sha256'),'hex'),
 'source_sha256',encode(extensions.digest(convert_to(prosrc,'UTF8'),'sha256'),'hex'),
 'ddl_bytes',octet_length(actual_ddl),'source_bytes',octet_length(prosrc))h
 FROM fn),
guard AS MATERIALIZED(SELECT count(*)=6 AND bool_and(h=expected)ok FROM headers),
bundle AS MATERIALIZED(SELECT jsonb_build_object('schema_version','tactics-staff-function-proof/1','functions',jsonb_agg(h ORDER BY signature))full_header_manifest,jsonb_object_agg(signature,h)target_bodies_after FROM headers HAVING count(*)=6),
witness AS MATERIALIZED(SELECT b.*,jsonb_build_object('sha256',public.combat_v2_sha256(full_header_manifest),'source_sha256','2cc1212cc0ad3d2de72b141a3a8c2c634c46b770c43c0e9ba55aa1f023e3c67f')compact FROM bundle b CROSS JOIN guard g WHERE g.ok),baseline AS MATERIALIZED(SELECT canonical_preimage::jsonb prior FROM mission_factory_owner.editor_release_readiness WHERE singleton AND revision_sha256='339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647' AND observed_revision_sha256=revision_sha256 AND public.combat_v2_sha256(canonical_preimage::jsonb)='339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647' AND octet_length(canonical_preimage)=524117),patched AS MATERIALIZED(SELECT prior,w.*,jsonb_set(prior,'{db_core,tactics_staff}',compact,false)j FROM baseline CROSS JOIN witness w),final AS MATERIALIZED(SELECT prior,full_header_manifest,target_bodies_after,compact,jsonb_set(j,'{db_core,sha256}',to_jsonb(public.combat_v2_sha256((j->'db_core')-'sha256')),false)successor FROM patched)SELECT jsonb_build_object('schema_version','tactics-root-projection/1','source_sha256','2cc1212cc0ad3d2de72b141a3a8c2c634c46b770c43c0e9ba55aa1f023e3c67f','parent_revision','339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647','full_header_manifest',full_header_manifest,'target_bodies_after',target_bodies_after,'compact',compact,'successor',successor,'canonical_preimage',successor::text,'revision_sha256',public.combat_v2_sha256(successor),'root_bytes',octet_length(successor::text),'db_sha256',successor#>>'{db_core,sha256}','untouched_outside_db_core',(successor-'db_core')=(prior-'db_core'))AS tactics_projection FROM final WHERE octet_length(successor::text)=524117 AND(successor-'db_core')=(prior-'db_core');
DO $integrated_adopt$
DECLARE tf_body text;tf_root jsonb;tf_bindings jsonb;tf_payload jsonb;tf_cert uuid;tf_count integer;tf_newRoot text;tf_review_ref text;tf_review_sha text;
BEGIN
IF NOT coalesce(((SELECT count(*)=1 AND bool_and((tactics_projection->>'root_bytes')::integer=524117 AND tactics_projection->>'source_sha256'='2cc1212cc0ad3d2de72b141a3a8c2c634c46b770c43c0e9ba55aa1f023e3c67f' AND(tactics_projection->>'untouched_outside_db_core')::boolean)FROM pg_temp.tactics_projected)),false)THEN RAISE EXCEPTION 'TACTICS_INTEGRATED_PROJECTED_ROOT';END IF;
 SELECT tactics_projection->>'canonical_preimage',tactics_projection->'successor',tactics_projection->>'revision_sha256'INTO STRICT tf_body,tf_root,tf_newRoot FROM pg_temp.tactics_projected;
 SELECT doc->>'ref',doc->>'sha256'INTO STRICT tf_review_ref,tf_review_sha FROM pg_temp.tactics_review;
 UPDATE mission_factory_owner.editor_release_readiness SET canonical_preimage=tf_body,
 revision_sha256=tf_newRoot,observed_revision_sha256=tf_newRoot,client_build='mission-factory-admin/2:'||tf_newRoot,
 independent_review_ref=tf_review_ref,updated_at=clock_timestamp() WHERE singleton AND revision_sha256='339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647';
 IF NOT coalesce((FOUND),false) THEN RAISE EXCEPTION 'COVERAGE_ROOT_CAS_WRITE'; END IF;
 tf_bindings:=jsonb_build_object('db_sha256',tf_root#>>'{db_core,sha256}','edge_sha256',tf_root#>>'{edge_bundles,0,ezbr_sha256}',
 'client_sha256',public.combat_v2_sha256(tf_root->'ui'),'configuration_sha256',tf_root#>>'{config,sha256}');
 INSERT INTO mission_public_owner.release_admissions_v1(release_sha256,db_sha256,edge_sha256,client_sha256,configuration_sha256,
 contract_version,independent_review_ref,staff_evidence_ref,qualified_at,public_enabled)
 SELECT tf_newRoot,tf_bindings->>'db_sha256',tf_bindings->>'edge_sha256',tf_bindings->>'client_sha256',
 tf_bindings->>'configuration_sha256',a.contract_version,tf_review_ref,a.staff_evidence_ref,clock_timestamp(),a.public_enabled
 FROM mission_public_owner.release_admissions_v1 a WHERE a.release_sha256='339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647';
 IF NOT coalesce((FOUND),false) THEN RAISE EXCEPTION 'COVERAGE_ADMISSION'; END IF;
 INSERT INTO mission_public_owner.engine_profile_events_v1(event_id,engine_release_sha256,profile_key,expected_control_version,
 control_version,authoring_enabled,runtime_enabled,reason)
 SELECT extensions.uuid_generate_v5('3ff627ec-dbee-423a-9879-8e37f7ad5510'::uuid,tf_newRoot||':profile:1'),tf_newRoot,p.profile_key,p.expected_control_version,
 p.control_version,p.authoring_enabled,p.runtime_enabled,'Preserve qualified predecessor scope during sole Staff Fenice deadline renewal; no new public tactics QA'
 FROM mission_public_owner.engine_profile_events_v1 p WHERE p.engine_release_sha256='339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647' AND p.profile_key='mission-ai-authoring/1'
 AND p.expected_control_version=0 AND p.control_version=1 AND p.authoring_enabled AND p.runtime_enabled;
 GET DIAGNOSTICS tf_count=ROW_COUNT;IF NOT coalesce((tf_count=1),false) THEN RAISE EXCEPTION 'COVERAGE_PROFILE'; END IF;
 SELECT q.payload||jsonb_build_object('revision_sha256',tf_newRoot,'bindings',tf_bindings,
 'independent_review',jsonb_build_object('ref',tf_review_ref,'sha256',tf_review_sha,'P0',0,'P1',0,'P2',0))
 INTO STRICT tf_payload FROM mission_public_owner.public_qualification_attestations_v1 q WHERE q.release_sha256='339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647';
 INSERT INTO mission_public_owner.public_qualification_attestations_v1(release_sha256,request_key,payload,payload_sha256,
 positive_staff_evidence_ref,authorized_test_manifest_ref,created_by)
 SELECT tf_newRoot,extensions.uuid_generate_v5('3ff627ec-dbee-423a-9879-8e37f7ad5510'::uuid,tf_newRoot||':qualification'),tf_payload,mission_factory_owner.sha(tf_payload),
 q.positive_staff_evidence_ref,q.authorized_test_manifest_ref,q.created_by
 FROM mission_public_owner.public_qualification_attestations_v1 q WHERE q.release_sha256='339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647';
 IF NOT coalesce((FOUND),false) THEN RAISE EXCEPTION 'COVERAGE_QUALIFICATION'; END IF;
 tf_cert:=extensions.uuid_generate_v5('3ff627ec-dbee-423a-9879-8e37f7ad5510'::uuid,tf_newRoot||':content-adoption');
 SELECT c.payload||jsonb_build_object('request_key',tf_cert,'engine_release_sha256',tf_newRoot,'created_at',clock_timestamp())
 INTO STRICT tf_payload FROM mission_public_owner.mission_content_admissions_v1 c WHERE c.engine_release_sha256='339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647';
 INSERT INTO mission_public_owner.mission_content_admissions_v1(request_key,mission_id,config_version,engine_release_sha256,
 publication_request,payload,payload_sha256)
 SELECT tf_cert,c.mission_id,c.config_version,tf_newRoot,c.publication_request,tf_payload,mission_factory_owner.sha(tf_payload)
 FROM mission_public_owner.mission_content_admissions_v1 c WHERE c.engine_release_sha256='339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647'
 AND c.mission_id='6d6c216a-222d-4cba-b2fc-f3e0c199c195'::uuid AND c.publication_request='3ff627ec-dbee-423a-9879-8e37f7ad5510'::uuid;
 IF NOT coalesce((FOUND),false) THEN RAISE EXCEPTION 'COVERAGE_CONTENT'; END IF;
 UPDATE mission_public_owner.party_launch_runtime_v1 SET release_sha256=tf_newRoot
 WHERE singleton AND release_sha256='339987736731c1721f25bc2a8bd36dd305f591c72443bc917c88d2d016a4c647' AND staff_enabled AND public_enabled;
 IF NOT coalesce((FOUND),false) THEN RAISE EXCEPTION 'COVERAGE_PARTY_CAS_WRITE'; END IF;
 IF NOT coalesce((mission_public_owner.engine_qualification_v1(tf_newRoot,true) IS NOT NULL),false) THEN RAISE EXCEPTION 'COVERAGE_NEW_ENGINE'; END IF;
 IF NOT coalesce((mission_public_owner.content_admission_v1('6d6c216a-222d-4cba-b2fc-f3e0c199c195'::uuid,tf_newRoot,'3ff627ec-dbee-423a-9879-8e37f7ad5510'::uuid,true) IS NOT NULL),false) THEN RAISE EXCEPTION 'COVERAGE_NEW_CONTENT'; END IF;

 PERFORM clan_innata_private.runtime_release_assert();
END $integrated_adopt$;

